let _harita = null;
function harita() {
  if (_harita) return _harita;
  _harita = new Map();
  for (const p of HAM.split('^')) {
    const i = p.indexOf('|');
    if (i > 0) _harita.set(p.slice(0, i), p.slice(i + 1));
  }
  return _harita;
}

/** Hanzi'nin İngilizce anlamı; yoksa null. */
export function anlamEn(h) { return harita().get(h) || null; }
/** Kayıt sayısı — mandal için. */
export function boy() { return harita().size; }

export default anlamEn;
